// Each chapter's question bank is its own lazily-loaded chunk (dynamic import), so the
// app only downloads the chapters you actually open. Chapter question COUNTS (used by the
// home screens) live in ./counts.js, which is generated by `npm run gen:counts` — it runs
// automatically before `npm run dev` and `npm run build`.
//
// Question schema:
// { id, type, question, options[], correctIndex, explanation, difficulty }
//
// To add a chapter: create banks/<file>.js exporting the array, then add a line to LOADERS.

import { QUESTION_COUNTS } from './counts';

export const LOADERS = {
  'unit-dimensions': () => import('./banks/unitDimensions').then(m => m.UNIT_DIMENSIONS),
  'motion-straight-line': () => import('./banks/motionStraightLine').then(m => m.MOTION_STRAIGHT_LINE),
  'electrostatics-potential-capacitance': () => import('./banks/electrostaticsPotentialCapacitance').then(m => m.ELECTROSTATICS_POTENTIAL_CAPACITANCE),
  'motion-plane': () => import('./banks/motionPlane').then(m => m.MOTION_PLANE),
  'laws-motion': () => import('./banks/lawsMotion').then(m => m.LAWS_MOTION),
  'work-energy-power': () => import('./banks/workEnergyPower').then(m => m.WORK_ENERGY_POWER),
  'system-particles-rotational-motion': () => import('./banks/rotationalMotion').then(m => m.SYSTEM_PARTICLES_ROTATIONAL_MOTION),
  'gravitation': () => import('./banks/gravitation').then(m => m.GRAVITATION),
  'mechanical-properties-solids': () => import('./banks/propertiesOfSolids').then(m => m.MECHANICAL_PROPERTIES_SOLIDS),
  'mechanical-properties-fluids': () => import('./banks/propertiesOfFluids').then(m => m.MECHANICAL_PROPERTIES_FLUIDS),
  'thermal-properties-matter': () => import('./banks/propertiesOfMatter').then(m => m.THERMAL_PROPERTIES_MATTER),
  'thermodynamics': () => import('./banks/thermodynamics').then(m => m.THERMODYNAMICS),
  'kinetic-theory': () => import('./banks/kineticTheory').then(m => m.KINETIC_THEORY),
  'oscillations': () => import('./banks/oscillations').then(m => m.OSCILLATIONS),
  'waves': () => import('./banks/waves').then(m => m.WAVES),
  'electric-charge-fields': () => import('./banks/electricChargesFields').then(m => m.ELECTRIC_CHARGES_FIELDS),
  'current-electricity': () => import('./banks/currentElecticity').then(m => m.CURRENT_ELECTRICITY),
  'moving-charges-magnetism': () => import('./banks/movingChargesMagnetism').then(m => m.MOVING_CHARGES_MAGNETISM),
  'magnetism-matters': () => import('./banks/magnetismMatter').then(m => m.MAGNETISM_MATTER),
  'electromagnetic-induction': () => import('./banks/electromagneticInduction').then(m => m.ELECTROMAGNETIC_INDUCTION),
  'alternating-current': () => import('./banks/alternatingCurrent').then(m => m.ALTERNATING_CURRENT),
  'electromagnetic-waves': () => import('./banks/electromagneticWaves').then(m => m.ELECTROMAGNETIC_WAVES),
  'ray-optics-optical-instruments': () => import('./banks/rayOptics').then(m => m.RAY_OPTICS_OPTICAL_INSTRUMENTS),
  'wave-optics': () => import('./banks/waveOptics').then(m => m.WAVE_OPTICS),
  'dual-nature-radiations-matter': () => import('./banks/dualNatureradiation').then(m => m.DUAL_NATURE_RADIATION_MATTER),
  'atoms': () => import('./banks/atoms').then(m => m.ATOMS),
  'nuclei': () => import('./banks/nuclei').then(m => m.NUCLEI),
  'semiconductor-electronics': () => import('./banks/semiconductorDevices').then(m => m.SEMICONDUCTORS_DEVICES),
};

const cache = {};

// Resolves to the chapter's question array ([] if the chapter has no bank).
export function getChapterQuestions(chapterId) {
  const load = LOADERS[chapterId];
  if (!load) return Promise.resolve([]);
  if (!cache[chapterId]) {
    cache[chapterId] = load().catch((err) => {
      delete cache[chapterId]; // allow a retry after a failed chunk download
      throw err;
    });
  }
  return cache[chapterId];
}

// Synchronous count for chapter cards / "chapters live" — no bank is downloaded.
export function getChapterQuestionCount(chapterId) {
  return QUESTION_COUNTS[chapterId] || 0;
}
